// This range holds no original (non-COMDAT) function: it is the sorted tail of the standard-library and ATL
// instantiations of guilddef.cpp. The instances come from the code of the other guilddef.cpp parts, which
// are separate sources here, so the container operations of those parts are driven from the function below.
typedef std::map<int,Unk_PayloadPtr<CGuildXmlData::GuildProperty>> Unk_PropertyMap;
typedef std::map<int,std::vector<Unk_PayloadPtr<CGuildXmlData::GuildSkill>>> Unk_SkillMap;
typedef std::map<int,Unk_PayloadPtr<CGuildXmlData::GuildEvent>> Unk_EventMap;
typedef std::map<std::pair<int,int>,Unk_PayloadPtr<CGuildXmlData::GuildHouse>> Unk_HouseMap;
typedef std::map<std::pair<Unk_GuildNpcKind,int>,Unk_PayloadPtr<CGuildXmlData::GuildNpc>> Unk_NpcMap;
typedef std::map<unsigned,Unk_PayloadPtr<CGuildXmlData::GuildRaid>> Unk_RaidMap;
typedef std::map<unsigned,Unk_PayloadPtr<CGuildNpcShop>> Unk_NpcShopMap;
typedef std::map<std::pair<unsigned,int>,ItemEntity> Unk_StorageMap;
typedef std::set<Unk_GuildNpcKind> Unk_NpcKindSet;

// Instantiate the real library helpers rather than hand-writing erased allocator
// bodies. ProductVec has 16-byte pointer elements; the old ItemEntity guesses
// incorrectly used the 48-byte value type for those vector COMDATs.
// ---- container driver: instantiates the std containers the CGuildXmlData parser/lookups use ----
template<class M,class K> void Unk_DriveMap(M& m,const K& key){
    typename M::iterator it=m.find(key);
    if(it!=m.end()) it->second;
    m[key];
    m.clear();
}
template<class V,class T> void Unk_DriveVector(V& v,const T& x){
    v.reserve(v.size());
    v.push_back(x);
    V copy(v);
    v=copy;
    V moved(std::move(copy));
    v=std::move(moved);
    v.insert(v.begin(),x);
    v.resize(v.size()+1);
    v.erase(v.begin());
    v.pop_back();
    v.assign(2,x);
    v.shrink_to_fit();
    T t(x);
    v.push_back(std::move(t));
    v.emplace_back(x);
    v.emplace_back(std::move(t));
    v.insert(v.begin(),std::move(t));
    V filled(3,x); V sized(3); V ranged(copy.begin(),copy.end());
    v.assign(ranged.begin(),ranged.end());
    v.insert(v.end(),3,x);
    v.insert(v.begin(),ranged.begin(),ranged.end());
    v.swap(copy);
}
void Unk_GuildDriveContainers(Unk_PropertyMap& a,Unk_SkillMap& b,Unk_EventMap& c,Unk_HouseMap& d,Unk_NpcMap& e,
                              Unk_RaidMap& f,Unk_NpcShopMap& g,Unk_StorageMap& h,Unk_NpcKindSet& i){
    Unk_DriveMap(a,0); Unk_DriveMap(b,0); Unk_DriveMap(c,0); Unk_DriveMap(d,std::pair<int,int>());
    Unk_DriveMap(e,std::pair<Unk_GuildNpcKind,int>()); Unk_DriveMap(f,0u); Unk_DriveMap(g,0u);
    Unk_DriveMap(h,std::pair<unsigned,int>());
    i.insert(Unk_GuildNpcKind_None); i.find(Unk_GuildNpcKind_None); i.clear();
    std::vector<int> vi; std::vector<unsigned> vu; std::vector<std::pair<int,int>> vp; std::vector<void*> vv;
    std::vector<Unk_PayloadPtr<CGuildXmlData::GuildSkill>> vs; std::vector<ItemEntity> ve; std::vector<Unk_GuildNpcKind> vk;
    Unk_DriveVector(vi,0); Unk_DriveVector(vu,0u); Unk_DriveVector(vp,std::pair<int,int>()); Unk_DriveVector(vv,(void*)0);
    Unk_DriveVector(vs,Unk_PayloadPtr<CGuildXmlData::GuildSkill>()); Unk_DriveVector(ve,ItemEntity()); Unk_DriveVector(vk,Unk_GuildNpcKind_None);
}

// These operations instantiate helpers from the original guild storage/shop
// containers. They are compilation drivers, never registered as runtime hooks.
void Unk_GuildDriveOther(guilddef4::ProductVec& products, guilddef4::HistDeque& history,
                        guilddef4::MapStorage2& storage, guilddef4::MapReward& rewards,
                        const guilddef4::TP<guilddef4::Hist>& entry) {
    Unk_DriveVector(products, guilddef4::TP<CNpcShopProductProxy>());
    history.push_back(entry);
    history.clear();
    Unk_DriveMap(storage, std::pair<__int64, int>());
    Unk_DriveMap(rewards, 0);
}
void Unk_GuildDriveProxy(std::_Container_proxy* destination, std::_Container_proxy& source) {
    std::allocator<std::_Container_proxy> allocator;
    std::allocator_traits<decltype(allocator)>::construct(allocator, destination, std::move(source));
}
int Unk_GuildDriveReverse(Unk_PropertyMap& properties, int limit) {
    int last = properties.rbegin()->first;
    return (std::max)(last, limit);
}
void Unk_GuildDriveAtl(void* buf) {
    new (buf) guilddef4::AtlEventMap();
    new (buf) guilddef4::AtlSkillMap();
    new (buf) guilddef4::AtlNpcMap();
    new (buf) guilddef4::AtlStrMap();
    new (buf) guilddef4::GradeArray();
    new (buf) guilddef4::HistArray();
    new (buf) guilddef4::MemberRBMap(10);
}
